import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

export const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

export const FIXED_DATE = '2026-10-20T12:00:00.000Z';

export const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  workspaceId: 'workspace-1',
  entries: [{role: 'user', content, timestamp: FIXED_DATE}],
  authHeaders: {},
});

export const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {promptBuilder, sessionWith, rejectingWith} from './onErrorNonError.testSupport.js';

const turnOutcome = async (reason: unknown) => {
  const callOrder: string[] = [];
  let seenError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      callOrder.push('onError');
      seenError = error;
    },
    afterSession: async () => {
      callOrder.push('afterSession');
    },
  };

  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});
  const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
    value => ({rejected: false, reason: value as unknown}),
    (thrown: unknown) => ({rejected: true, reason: thrown})
  );

  return {
    outcome,
    callOrder,
    isError: seenError instanceof Error,
    message: seenError?.message,
    cause: seenError?.cause,
  };
};

describe('ChatOrchestrator onError on non-Error rejections (acceptance)', () => {
  it('calls onError with an Error carrying the thrown string and runs afterSession while rethrowing', async () => {
    const result = await turnOutcome('string boom');

    expect(result).toMatchObject({
      outcome: {rejected: true, reason: 'string boom'},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      message: 'string boom',
      cause: 'string boom',
    });
  });

  it('calls onError with an Error carrying a readable message when the stream rejects with a plain object', async () => {
    const reason = {code: 503, detail: 'upstream down'};

    const result = await turnOutcome(reason);

    expect(result).toMatchObject({
      outcome: {rejected: true, reason},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      message: expect.stringMatching(/.+/),
      cause: reason,
    });
  });
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {promptBuilder, sessionWith, rejectingWith} from './onErrorNonError.testSupport.js';

describe('ChatOrchestrator onError non-Error coercion (facet)', () => {
  it('coerces a thrown string to an Error for the onError hook', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith('string boom'), promptBuilder, undefined, {hooks});

    // We expect it to still throw the original string to the caller
    await expect(orchestrator.processMessage(sessionWith('hello'))).rejects.toBe('string boom');

    expect(receivedError).toMatchObject({
      message: 'string boom',
      cause: 'string boom',
    });
  });

  it('coerces undefined to an Error for the onError hook', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(undefined), promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(sessionWith('hello'))).rejects.toBeUndefined();

    expect(receivedError).toMatchObject({
      message: 'undefined',
      cause: undefined,
    });
  });

  it('passes an existing Error instance through unchanged to the onError hook', async () => {
    const originalError = new Error('existing error');
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(originalError), promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(sessionWith('hello'))).rejects.toThrow(originalError);

    expect(receivedError).toBe(originalError);
  });
});

